before:
public class ClickCounter {
    public int n;

    public void click() {
        n++;
    }

    public void reset() {
        n = 0;
    }
}

after:
public class ClickCounter {
    public int count;

    public void click() {
        count++;
    }

    public void reset() {
        count = 0;
    }
}

test:
public class Test {
    public static void main(String[] a) {
        ClickCounter c = new ClickCounter();
        c.click(); c.click();
        if (!(c.count == 2)) throw new AssertionError("after two clicks");
        c.reset();
        if (!(c.count == 0)) throw new AssertionError("after reset");
        System.out.println("PASS");
    }
}
